const CACHE_PREFIX = 'knit-studio-shell-';
const CACHE_NAME = CACHE_PREFIX + OFFLINE_VERSION;
const SCOPE_URL = new URL(self.registration.scope);
const INDEX_URL = new URL('index.html', SCOPE_URL).href;
const ASSET_BY_URL = new Map(OFFLINE_ASSETS.map(asset => [new URL(asset.path, SCOPE_URL).href, asset]));
const APP_MARKER = /<meta\b(?=[^>]*\bname\s*=\s*["']knit-studio-app["'])(?=[^>]*\bcontent\s*=\s*["']offline-v1["'])[^>]*>/i;

async function validateResponse(response, asset, url) {
  if (!response || response.status !== 200 || response.redirected || response.type === 'opaque' || response.type === 'opaqueredirect') {
    throw new Error('Offline asset unavailable: ' + asset.path);
  }
  if (response.url && response.url !== url) throw new Error('Offline asset changed destination: ' + asset.path);
  const type = (response.headers.get('Content-Type') || '').split(';')[0].trim().toLowerCase();
  if (!asset.types.includes(type)) throw new Error('Offline asset has an unexpected type: ' + asset.path);
  if (asset.path === 'index.html') {
    // Hosting may inject platform markup. Accept only our marked shell; never a sign-in page.
    // Its source digest still participates in OFFLINE_VERSION, but injected HTML is not byte-pinned.
    if (!APP_MARKER.test(await response.clone().text())) throw new Error('Offline page is not Knit Studio');
  } else {
    // Pin executable code and other assets to this release, including cache repairs after an update.
    const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
    const hex = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
    if (hex !== asset.sha256) throw new Error('Offline asset belongs to a different release: ' + asset.path);
  }
  return response;
}

async function downloadAsset(url, asset) {
  const response = await fetch(url, { credentials: 'same-origin', cache: 'reload', redirect: 'error' });
  return validateResponse(response, asset, url);
}

async function completeCache(cache) {
  for (const url of ASSET_BY_URL.keys()) if (!await cache.match(url)) return false;
  return true;
}

async function fillMissing(cache) {
  // Sequential writes make failure cleanup deterministic; a late parallel put cannot recreate a partial cache.
  for (const [url, asset] of ASSET_BY_URL) {
    if (!await cache.match(url)) await cache.put(url, await downloadAsset(url, asset));
  }
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    if (await completeCache(cache)) return;
    try {
      await fillMissing(cache);
      if (!await completeCache(cache)) throw new Error('Offline installation is incomplete');
    } catch (error) {
      // A failed candidate must not remove the currently active, previously installed release.
      await caches.delete(CACHE_NAME);
      throw error;
    }
    // Intentionally no skipWaiting(): an update must not replace a page while somebody is drawing.
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    if (!await completeCache(cache)) throw new Error('Cannot activate an incomplete offline release');
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== SCOPE_URL.origin || url.search || url.hash) return;
  const key = url.href === SCOPE_URL.href ? INDEX_URL : url.href;
  const asset = ASSET_BY_URL.get(key);
  if (!asset) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cached = await cache.match(key);
    if (cached) return cached;
    const response = await downloadAsset(key, asset);
    // A full cache can be evicted independently of the worker. Repair only validated release bytes.
    await cache.put(key, response.clone());
    return response;
  })());
});

self.addEventListener('message', event => {
  if (!event.data || !['KNIT_OFFLINE_STATUS', 'KNIT_OFFLINE_PREPARE'].includes(event.data.type) || !event.ports || !event.ports[0]) return;
  const port = event.ports[0];
  event.waitUntil((async () => {
    let ready = false;
    try {
      const cache = await caches.open(CACHE_NAME);
      if (event.data.type === 'KNIT_OFFLINE_PREPARE') await fillMissing(cache);
      ready = await completeCache(cache);
    } catch (_) {
      // Repair preserves usable entries. A failed check or repair must never claim offline readiness.
    }
    port.postMessage({ type: 'KNIT_OFFLINE_STATUS', ready, version: OFFLINE_VERSION, assetCount: OFFLINE_ASSETS.length });
  })());
});
